import{_ as e,c as a,o as r,V as i}from"./chunks/framework.e2d10ea7.js";const _=JSON.parse('{"title":"微前端","description":"","frontmatter":{},"headers":[],"relativePath":"front-end-architects/micro-front-end/index.md","filePath":"front-end-architects/micro-front-end/index.md"}'),l={name:"front-end-architects/micro-front-end/index.md"},t=i('<h1 id="微前端" tabindex="-1">微前端 <a class="header-anchor" href="#微前端" aria-label="Permalink to &quot;微前端&quot;">​</a></h1><h2 id="什么是微前端" tabindex="-1">什么是微前端 <a class="header-anchor" href="#什么是微前端" aria-label="Permalink to &quot;什么是微前端&quot;">​</a></h2><p>微前端是一种类似于微服务的架构，是一种由独立交付的多个前端应用组成整体的架构风格，将前端应用分解成一些更小、更简单的能够独立开发、测试、部署的应用，而在用户看来仍然是内聚的单个产品。</p><h2 id="微前端产生的背景" tabindex="-1">微前端产生的背景 <a class="header-anchor" href="#微前端产生的背景" aria-label="Permalink to &quot;微前端产生的背景&quot;">​</a></h2><p>在提倡拥抱变化的前端社区可以看到新的框架、技术、概念层出不穷，并且随着 Web 标准的演进，前端应用已经具备更好的性能、更快的开发效率。但随着而来的是应用的复杂程度更高、涉及的团队规模更广、更高的性能要求，应用复杂度已经成为阻塞业务发展的重要瓶颈。</p><p>尽管 Web 应用的复杂度和参与人数以爆炸式的增长速度，但却没有一种新的架构模式来解决现有的困境，并同时兼顾 DX（developer experience）和 UX（user experience）。</p><p>由于 Web 应用在逐步取代传统的 PC 软件时，大规模 Web 应用在面对高复杂度和涉及团队成员广下无法同时保证 DX 和 UX 的困境。传统的分而治之的策略已经无法应对现代 Web 应用的复杂性，因此衍生出了微前端这样一种新的架构模式，与后端微服务相同，它同样是延续了分而治之的设计模式，不过却以全新的方法来实现。</p><h2 id="微前端的优点" tabindex="-1">微前端的优点 <a class="header-anchor" href="#微前端的优点" aria-label="Permalink to &quot;微前端的优点&quot;">​</a></h2><ul><li>适用于大规模 Web 应用的开发</li><li>更快的开发速度</li><li>支持迭代可开发和增强升级</li><li>拆解后的部分降低了开发者的理解成本</li><li>同时具备 UX 和 DX 的开发模式</li></ul><h2 id="微前端的缺点" tabindex="-1">微前端的缺点 <a class="header-anchor" href="#微前端的缺点" aria-label="Permalink to &quot;微前端的缺点&quot;">​</a></h2><ul><li>复杂度从代码转向基础设施</li><li>整个应用的稳定性和安全性变得更加不可控</li><li>具备一定的学习和了解成本</li><li>需要建立全面的微前端周边设施，才能充分发挥其架构的优势 （调试工具、监控系统、上层 Web 框架、部署平台）</li></ul><h2 id="何时采用微前端" tabindex="-1">何时采用微前端 <a class="header-anchor" href="#何时采用微前端" aria-label="Permalink to &quot;何时采用微前端&quot;">​</a></h2><ul><li>大规模企业级 Web 应用开发</li><li>跨团队及企业级应用协作开发</li><li>长期收益高于短期收益</li><li>不同技术选型的项目</li><li>内聚的单个产品中部分需要独立发布、灰度等能力</li><li>微前端的目标并非用于取代 Iframe （应用的来源必须可信、用户体验要求更高）</li></ul><h2 id="众所周知的微前端框架" tabindex="-1">众所周知的微前端框架 <a class="header-anchor" href="#众所周知的微前端框架" aria-label="Permalink to &quot;众所周知的微前端框架&quot;">​</a></h2><ul><li>Garfish （字节跳动所用）</li></ul><p><a href="https://www.garfishjs.org/" target="_blank" rel="noreferrer">Garfish</a></p><ul><li>MicroApp (京东所用)</li></ul><p><a href="https://micro-zoe.github.io/micro-app/" target="_blank" rel="noreferrer">MicroApp</a></p><ul><li>qiankun (阿里所用 【蚂蚁金服基于 single-spa开发】)</li></ul><p><a href="https://qiankun.umijs.org/zh/" target="_blank" rel="noreferrer">qiankun</a></p><ul><li>wujie (开发组织： 腾讯)</li></ul><p><a href="https://gitee.com/mirrors/wujie" target="_blank" rel="noreferrer">无界</a></p><ul><li>icestark (阿里所用【钉钉、飞猪、淘宝、阿里云】)</li></ul><p><a href="https://micro-frontends.ice.work/" target="_blank" rel="noreferrer">icestark</a></p>',24),o=[t];function n(h,s,c,d,p,u){return r(),a("div",null,o)}const b=e(l,[["render",n]]);export{_ as __pageData,b as default};
